#!/usr/bin/env node
'use strict';

const crypto = require('node:crypto');
const fs = require('node:fs');
const path = require('node:path');
const { domainModelRevision, validatePrototypeDomainModel } = require('../../../scripts/lib/prototype-domain-model');

const MARKER = 'Generated by prototype-to-real-app/gen-dataverse-repositories.js';

function sha256(value) {
  return crypto.createHash('sha256').update(value).digest('hex');
}

function readJson(filePath, label) {
  try {
    return JSON.parse(fs.readFileSync(filePath, 'utf8'));
  } catch (error) {
    throw new Error(`${label} is invalid JSON: ${error.message}`);
  }
}

function identifier(value) {
  const safe = String(value || '').replace(/[^A-Za-z0-9_$]/g, '');
  if (!safe || !/^[A-Za-z_$]/.test(safe)) throw new Error(`unsafe TypeScript identifier ${value}`);
  return safe;
}

function lowerIdentifier(value) {
  const safe = identifier(value);
  return safe.charAt(0).toLowerCase() + safe.slice(1);
}

function readExpression(entityMapping, field) {
  const source = `row[${JSON.stringify(field.dataverseField)}]`;
  const optional = (expression) => field.required ? expression : `${source} == null ? undefined : (${expression})`;
  if (field.transform === 'boolean') return optional(`Boolean(${source})`);
  if (field.transform === 'number') return optional(`Number(${source})`);
  if (field.transform === 'money') return optional(`{ amount: Number(${source}), currencyCode: ${JSON.stringify(field.defaultCurrencyCode)} }`);
  if (field.transform === 'choice') return optional(`decodeChoice(${JSON.stringify(field.choiceMap || {})}, ${source}, ${JSON.stringify(`${entityMapping.domainEntity}.${field.domainField}`)})`);
  if (field.transform === 'image-url') {
    const altMapping = entityMapping.fields.find((candidate) => candidate.domainField === field.altTextField);
    const alt = altMapping
      ? `String(row[${JSON.stringify(altMapping.dataverseField)}] ?? ${JSON.stringify(entityMapping.domainEntity)})`
      : JSON.stringify(entityMapping.domainEntity);
    return optional(`{ imageUrl: String(${source}), imageAltText: ${alt}, imageAssetKey: \`dataverse://${entityMapping.domainEntity}/\${String(row[${JSON.stringify(entityMapping.primaryIdAttribute)}])}/${field.domainField}\`, family: 'product' as const }`);
  }
  return optional(`String(${source})`);
}

function queryExpression(field, expression) {
  if (field.transform === 'money') return `${expression}.amount`;
  if (field.transform === 'choice') return `encodeChoice(${JSON.stringify(field.choiceMap || {})}, ${expression}, ${JSON.stringify(field.domainField)})`;
  if (field.transform === 'image-url') return `${expression}.imageUrl`;
  return expression;
}

function writeExpression(field, expression) {
  if (field.transform === 'reference') return `bindReference(${JSON.stringify(field.targetEntitySetName)}, ${expression})`;
  return queryExpression(field, expression);
}

function renderEntityMapper(entity, entityMapping) {
  const fields = entityMapping.fields
    .map((field) => `    ${field.domainField}: ${readExpression(entityMapping, field)},`)
    .join('\n');
  const writeFields = entityMapping.fields
    .filter((field) => field.transform !== 'id')
    .map((field) => `  if (input.${field.domainField} !== undefined) payload[${JSON.stringify(field.writeField || field.dataverseField)}] = ${writeExpression(field, `input.${field.domainField}`)};`)
    .join('\n');
  return `function map${identifier(entity.key)}(row: DataverseRow): ${identifier(entity.key)} {\n  return {\n${fields}\n  } as ${identifier(entity.key)};\n}\n\nfunction write${identifier(entity.key)}(input: Partial<${identifier(entity.key)}>): DataverseRow {\n  const payload: DataverseRow = {};\n${writeFields}\n  return payload;\n}`;
}

function operationImplementation(operation, entityMapping) {
  const service = identifier(operation.service);
  const mapper = `map${identifier(operation.domainEntity)}`;
  const writer = `write${identifier(operation.domainEntity)}`;
  if (operation.kind === 'list') {
    const filters = Object.entries(operation.filters || {}).map(([domainField, dataverseField]) => {
      const field = entityMapping.fields.find((candidate) => candidate.domainField === domainField);
      const encoded = field.transform === 'reference'
        ? `odataGuid(input.${domainField})`
        : `odataLiteral(${queryExpression(field, `input.${domainField}`)})`;
      return `      if (input?.${domainField} !== undefined) filters.push(${JSON.stringify(dataverseField)} + ' eq ' + ${encoded});`;
    }).join('\n');
    const orderBy = Object.values(operation.sort || {}).map((field) => `${field} asc`);
    return `    async ${operation.method}(input = {}) {\n      const filters: string[] = [];\n${filters}\n      const result = await ${service}.getAll({\n        select: ${JSON.stringify(operation.select)},\n        orderBy: ${JSON.stringify(orderBy)},\n        ...(filters.length ? { filter: filters.join(' and ') } : {}),\n        ...(input.pageSize ? { maxPageSize: input.pageSize } : {}),\n        ...(input.cursor ? { skipToken: input.cursor } : {}),\n      });\n      const cursor = nextCursor(result);\n      return { data: rowsFrom(result).map(${mapper}), ...(cursor ? { nextCursor: cursor } : {}) };\n    },`;
  }
  if (operation.kind === 'get') return `    async ${operation.method}(id) {\n      const result = await ${service}.get(id, { select: ${JSON.stringify(operation.select)} });\n      const row = rowFrom(result);\n      return row ? ${mapper}(row) : null;\n    },`;
  if (operation.kind === 'create') return `    async ${operation.method}(input) {\n      const id = newId();\n      await ${service}.create({ ...${writer}(input), [${JSON.stringify(entityMapping.primaryIdAttribute)}]: id } as any);\n      const row = rowFrom(await ${service}.get(id, { select: ${JSON.stringify(operation.select)} }));\n      if (!row) throw new Error(${JSON.stringify(`${operation.domainOperation} could not refetch the created record`)});\n      return ${mapper}(row);\n    },`;
  if (operation.kind === 'update') return `    async ${operation.method}({ id, patch }) {\n      await ${service}.update(id, ${writer}(patch));\n      const row = rowFrom(await ${service}.get(id, { select: ${JSON.stringify(operation.select)} }));\n      if (!row) throw new Error(${JSON.stringify(`${operation.domainOperation} could not refetch the updated record`)});\n      return ${mapper}(row);\n    },`;
  return `    async ${operation.method}(id) { await ${service}.delete(id); },`;
}

function renderAdapters(model, mapping) {
  const services = new Map(mapping.entities.map((entity) => [entity.service, entity.serviceModule]));
  const serviceImports = [...services.entries()]
    .map(([service, module]) => `import { ${identifier(service)} } from ${JSON.stringify(module)};`)
    .join('\n');
  const entityTypes = mapping.entities.map((entity) => identifier(entity.domainEntity)).join(', ');
  const repositoryTypes = [...new Set(model.operations.map((operation) => identifier(operation.repository)))].join(', ');
  const idImport = mapping.operations.some((operation) => operation.kind === 'create') ? "import { newId } from '@/utils';\n" : '';
  const mappers = mapping.entities.map((entityMapping) => {
    const entity = model.entities.find((candidate) => candidate.key === entityMapping.domainEntity);
    return renderEntityMapper(entity, entityMapping);
  }).join('\n\n');
  const repositories = [...new Set(model.operations.map((operation) => operation.repository))].map((repository) => {
    const operations = mapping.operations.filter((operation) => operation.repository === repository);
    const methods = operations.map((operation) => operationImplementation(
      operation,
      mapping.entities.find((entity) => entity.domainEntity === operation.domainEntity),
    )).join('\n');
    return `  const ${lowerIdentifier(repository)}: ${identifier(repository)} = {\n${methods}\n  };`;
  }).join('\n');
  const returnFields = [...new Set(model.operations.map((operation) => operation.repository))]
    .map((repository) => `    ${identifier(repository)}: ${lowerIdentifier(repository)},`)
    .join('\n');
  return `// ${MARKER}
import type { ${entityTypes} } from '../model';
import type { DomainRepositoryMap, ${repositoryTypes} } from '../contracts';
${idImport}${serviceImports}

type DataverseRow = Record<string, any>;

function rowsFrom(result: any): DataverseRow[] {
  if (Array.isArray(result)) return result;
  const rows = result?.data ?? result?.value ?? result?.items ?? [];
  return Array.isArray(rows) ? rows : [];
}

function rowFrom(result: any): DataverseRow | null {
  const row = result?.data ?? result;
  return row && !Array.isArray(row) && typeof row === 'object' ? row : null;
}

function nextCursor(result: any): string | undefined {
  return result?.skipToken ?? result?.nextSkipToken ?? result?.skiptoken;
}

function odataLiteral(value: unknown): string {
  if (typeof value === 'number' || typeof value === 'boolean') return String(value);
  return \`'\${String(value).replace(/'/g, "''")}\'\`;
}

function odataGuid(value: unknown): string {
  const id = String(value);
  if (!/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(id)) throw new Error(\`Invalid Dataverse record ID: \${id}\`);
  return id;
}

function bindReference(entitySetName: string, value: unknown): string {
  return \`/\${entitySetName}(\${odataGuid(value)})\`;
}

function decodeChoice(map: Record<string, string | number>, value: unknown, label: string): any {
  const match = Object.entries(map).find(([, mapped]) => String(mapped) === String(value));
  if (!match) throw new Error(\`Unknown Dataverse choice value for \${label}: \${String(value)}\`);
  return match[0];
}

function encodeChoice(map: Record<string, string | number>, value: unknown, label: string): string | number {
  const mapped = map[String(value)];
  if (mapped === undefined) throw new Error(\`Unknown domain choice key for \${label}: \${String(value)}\`);
  return mapped;
}

${mappers}

export function createDataverseRepositories(): DomainRepositoryMap {
${repositories}
  return {
${returnFields}
  };
}
`;
}

function validateMapping(projectRoot, model, mapping) {
  const errors = [];
  if (mapping.schemaVersion !== 1) errors.push('mapping.schemaVersion must be 1');
  if (mapping.domainModelRevision !== domainModelRevision(model)) errors.push('mapping domainModelRevision is stale');
  const manifestPath = path.join(projectRoot, '.datamodel-manifest.json');
  if (!fs.existsSync(manifestPath) || mapping.dataverseManifestSha256 !== sha256(fs.readFileSync(manifestPath))) errors.push('mapping Dataverse manifest hash is stale');
  for (const entity of model.entities) {
    const mapped = mapping.entities?.find((candidate) => candidate.domainEntity === entity.key);
    if (!mapped) errors.push(`mapping is missing entity ${entity.key}`);
    for (const field of entity.fields.filter((candidate) => candidate.required)) {
      const mappedField = mapped?.fields?.find((candidate) => candidate.domainField === field.key);
      if (!mappedField) errors.push(`mapping is missing required field ${entity.key}.${field.key}`);
      if (field.type === 'reference' && (!mappedField?.writeField || !mappedField?.targetEntitySetName)) errors.push(`mapping reference ${entity.key}.${field.key} is missing write binding metadata`);
    }
  }
  for (const operation of model.operations) if (!mapping.operations?.some((candidate) => candidate.domainOperation === operation.key)) errors.push(`mapping is missing operation ${operation.key}`);
  return errors;
}

function generateDataverseRepositories(projectRoot) {
  const root = fs.realpathSync(path.resolve(projectRoot));
  const model = readJson(path.join(root, '.tmp', 'prototype-domain-model.json'), 'Prototype domain model');
  const domainValidation = validatePrototypeDomainModel(model);
  if (!domainValidation.valid) throw new Error(`prototype domain model is invalid: ${domainValidation.errors.join('; ')}`);
  const report = readJson(path.join(root, '.tmp', 'dataverse-reconciliation-report.json'), 'Dataverse reconciliation report');
  if (report.status !== 'ready' || report.conflicts?.length) throw new Error('Dataverse reconciliation has unresolved conflicts');
  const mapping = readJson(path.join(root, '.tmp', 'dataverse-repository-mapping.json'), 'Dataverse repository mapping');
  if (report.domainModelRevision !== mapping.domainModelRevision || report.dataverseManifestSha256 !== mapping.dataverseManifestSha256) {
    throw new Error('Dataverse reconciliation report and repository mapping revisions do not match');
  }
  const errors = validateMapping(root, model, mapping);
  if (errors.length) throw new Error(errors.join('; '));
  const target = path.join(root, 'src', 'data', 'repositories', 'dataverseRepositories.ts');
  if (fs.existsSync(target) && fs.lstatSync(target).isSymbolicLink()) throw new Error('Dataverse repository target must not be a symlink');
  const source = renderAdapters(model, mapping);
  fs.mkdirSync(path.dirname(target), { recursive: true });
  const temporary = `${target}.tmp-${process.pid}`;
  try {
    fs.writeFileSync(temporary, source, { flag: 'wx' });
    fs.renameSync(temporary, target);
  } finally {
    fs.rmSync(temporary, { force: true });
  }
  return { target: 'src/data/repositories/dataverseRepositories.ts', sha256: sha256(source), domainModelRevision: domainModelRevision(model) };
}

function main(argv) {
  if (!argv[0]) {
    process.stderr.write('Usage: node gen-dataverse-repositories.js <project-dir>\n');
    return 2;
  }
  try {
    process.stdout.write(`${JSON.stringify(generateDataverseRepositories(argv[0]), null, 2)}\n`);
    return 0;
  } catch (error) {
    process.stderr.write(`BLOCKED: Dataverse repository generation: ${error.message}\n`);
    return 2;
  }
}

if (require.main === module) process.exitCode = main(process.argv.slice(2));

module.exports = { generateDataverseRepositories, renderAdapters, validateMapping };